compile.workshop:
variables {
    global:
        0: index
        1: values
    player:
        0: savedEffect
}

rule ("Apply hero selection context") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Is In Spawn Room(Event Player) == True;
        Is Moving(Event Player) == False;
        Global.index == Null;
    }
    actions {
        Set Global Variable(index, False);
        Set Global Variable(values, Array(Null, Null));
        Set Global Variable At Index(values, True, Null);
        Set Player Variable(Event Player, savedEffect, Null);
        Set Status(Event Player, Null, Invincible, False);
        Create Effect(Null, Ring, Color(Red), Vector(False, True, False), False, Visible To);
        Wait(False, Ignore Condition);
        For Global Variable(index, False, True, False);
        End;
    }
}

